-- Expand the existing public catalogue. Keep the original column/RPC signature valid for old deployments.
alter table public.study_promotions add column destinations text[] not null default '{}';
alter table public.study_promotions add column catalogue_key text unique;
update public.study_promotions set destinations=array[destination];

create function private.sync_programme_destinations() returns trigger
language plpgsql set search_path='' as $$
declare place text;
begin
  if cardinality(new.destinations)=0 then new.destinations=array[new.destination];
  elsif tg_op='UPDATE' and new.destination is distinct from old.destination and new.destinations=old.destinations then
    new.destinations=array[new.destination];
  end if;
  if cardinality(new.destinations) not between 1 and 250 or array_ndims(new.destinations)<>1 then
    raise exception 'Choose valid destinations'; end if;
  foreach place in array new.destinations loop
    if place is null or length(trim(place)) not between 1 and 100 then raise exception 'Choose valid destinations'; end if;
  end loop;
  if cardinality(new.destinations)<>(select count(distinct p) from unnest(new.destinations) p) then
    raise exception 'Choose distinct destinations'; end if;
  new.destination=new.destinations[1];
  return new;
end $$;
create trigger sync_programme_destinations before insert or update on public.study_promotions
for each row execute function private.sync_programme_destinations();
revoke all on function private.sync_programme_destinations() from public,anon,authenticated;

create or replace function public.save_study_promotion(p_id uuid,p_data jsonb) returns uuid
language plpgsql security definer set search_path='' as $$
declare result uuid; places text[];
begin
  if not private.has_role(array['admin']::public.staff_role[]) then raise exception 'Access denied'; end if;
  if p_data ? 'destinations' then
    select array_agg(value order by ordinal) into places from jsonb_array_elements_text(p_data->'destinations') with ordinality as p(value,ordinal);
    if coalesce(cardinality(places),0)=0 then raise exception 'Choose destinations'; end if;
  else places=array[p_data->>'destination']; end if;
  if not private.valid_marketing_image(p_data->>'image') then raise exception 'Choose an approved image'; end if;
  values(coalesce(p_id,gen_random_uuid()),p_data->>'title',places[1],places,p_data->>'studyLevel',p_data->>'field',p_data->>'fundingType',p_data->>'eligibility',p_data->>'image',(p_data->>'published')::boolean)
  on conflict(id) do update set title=excluded.title,destination=excluded.destination,destinations=excluded.destinations,
    study_level=excluded.study_level,field=excluded.field,funding_type=excluded.funding_type,eligibility=excluded.eligibility,
    image=excluded.image,published=excluded.published,updated_at=now() returning id into result;
  return result;
end $$;

-- Existing stage values and audit history remain readable. Normalize writes from older clients.
create function private.simplify_consultation_stage() returns trigger
language plpgsql set search_path='' as $$
begin
  new.stage=case new.stage when 'converted' then 'qualified'::public.lead_stage
    when 'not_currently_eligible' then 'closed'::public.lead_stage else new.stage end;
  return new;
end $$;
create trigger simplify_consultation_stage before insert or update of stage on public.leads
for each row execute function private.simplify_consultation_stage();
revoke all on function private.simplify_consultation_stage() from public,anon,authenticated;

-- The 60 shipped guides follow below, copied verbatim from the existing editorial catalogue.
-- They retain the four destinations previously offered by the shared catalogue.
on conflict(catalogue_key) do nothing;
